record.field:
# Action: build sensors plan (robust JSON parsing with SQL optimization)
Remote = self.remote_id
Sensor = env['mdm.measurement.device.sensor']
Reading = env['mdm.measurement.device.sensor.reading']
today_str = fields.Date.today()
condition = [
    ('remotecontrol_params','!=',False),
    ('device_id.remotecontrol_id', '=', Remote.id)
]
selected_device_id = bag.get('selected_device_id')
if selected_device_id:
    condition.append(('device_id', '=', selected_device_id))
sensors = Sensor.search(condition)
# Optimize: build map of sensor_id -> most recent reading (single query)
last_readings_map = {}
if sensors:
    sensor_ids = [s.id for s in sensors]
    cr = env.cr
    cr.execute(
        'SELECT DISTINCT ON (sensor_id) sensor_id, measurement_time '
        'FROM mdm_measurement_device_sensor_reading '
        'WHERE sensor_id IN %s AND active = TRUE '
        'ORDER BY sensor_id, measurement_time DESC',
        (tuple(sensor_ids),)
    )
    for row in cr.fetchall():
        last_readings_map[row[0]] = row[1]
# Now iterate sensors using the map
plan = []
for sensor in sensors:
    device = sensor.device_id
    try:
        sensor_cfg = json.loads(sensor.remotecontrol_params or '{}') or {}
    except Exception:
        sensor_cfg = {}
    sensor_parameter = (sensor_cfg.get('sensor_id') or '').strip()
    if sensor_parameter not in (None,''):
        try:
            device_cfg = json.loads(device.remotecontrol_params or '{}') or {}
        except Exception:
            device_cfg = {}
        device_parameter = (device_cfg.get('device_id') or '').strip()
        if device_parameter:
            # Retrieve last_reading from map (no query per sensor)
            last_reading_time = last_readings_map.get(sensor.id)
            if last_reading_time:
                try:
                    initial_date = fields.Date.to_string(
                        fields.Datetime.from_string(last_reading_time) +
                        timedelta(days=1))
                except Exception:
                    initial_date = str(last_reading_time)[:10]
            else:
                start_cfg = (sensor_cfg.get('start_date') or device_cfg.get('start_date'))
                if start_cfg:
                    initial_date = start_cfg[:10]
                else:
                    year_str = today_str[:4]
                    initial_date = '%s-01-01' % year_str
            level = sensor_cfg.get('level', '')
            plan.append({
                'sensor_id': sensor.id,
                'device_id': device.id,
                'sensor_parameter': sensor_parameter,
                'device_parameter': device_parameter,
                'level': level,
                'initial_date': initial_date,
            })
bag['sensors_plan'] = plan

remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}
token = (cfg.get('token') or '').strip()
if not token:
    raise Exception("Missing ODINS token in connection_params.")
base_url = remote.base_url.rstrip('/')
headers = {'x-access-token': token}
url = '%s/backend/v2/entities/' % base_url
resp = request_retry('GET', url, headers=headers, timeout=timeout)
if resp.status_code >= 400:
    raise Exception("Error fetching devices: %s %s" % (resp.status_code, resp.text))
devices = resp.json() or []
devices_list = []
total_devices = 0
total_sensors = 0
for device in devices:
    device_id = device.get('id')
    if not device_id:
        continue
    device_name = device.get('name', device_id)
    serial_number = device.get('serialNumber', device_id)
    if isinstance(serial_number, dict):
        serial_number = serial_number.get('value', device_id)
    device_info = {
        'odins_id': device_id,
        'name': device_name,
        'serial_number': serial_number,
        'sensors': []
    }
    for attr_name, attr_data in device.items():
        if attr_name in ['id', 'type', 'name', 'serialNumber', 'dateModified']:
            continue
        if not isinstance(attr_data, dict):
            continue
        attr_type = attr_data.get('type', 'Text')
        attr_value = attr_data.get('value')
        unit_code = ''
        metadata = attr_data.get('metadata', {})
        if isinstance(metadata, dict):
            unit_code_data = metadata.get('unitCode', {})
            if isinstance(unit_code_data, dict):
                unit_code = unit_code_data.get('value', '')
            else:
                unit_code = str(unit_code_data) if unit_code_data else ''
        sensor_info = {
            'sensor_id': attr_name,
            'type': attr_type,
            'unit_of_measure': unit_code
        }
        if attr_type == 'StructuredValue' and isinstance(attr_value, dict):
            sensor_info['has_levels'] = True
            sensor_info['levels'] = {}
            for level_key, level_value in attr_value.items():
                clean_key = level_key[1:] if level_key and level_key[0] in 'THSP' else level_key
                sensor_info['levels'][clean_key] = level_value
                total_sensors += 1
        else:
            sensor_info['has_levels'] = False
            total_sensors += 1
        device_info['sensors'].append(sensor_info)
    devices_list.append(device_info)
    total_devices += 1
data = {
    'procedure': 'ODINS: Get Devices (All)',
    'executed_at': fields.Datetime.now(),
    'summary': {
        'total_devices': total_devices,
        'total_sensors': total_sensors,
        'total_api_entities': len(devices)
    },
    'devices': devices_list
}
json_str = json.dumps(data, ensure_ascii=False, indent=2)
encoded = base64.b64encode(json_str.encode('utf-8'))
timestamp = fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
fname = 'odins_devices_sensors_%s.json' % timestamp
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': encoded,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': remote.id
})
remote.message_post(
    body='[ODINS] Devices=%s Sensors=%s - JSON generated for import preparation' % (total_devices, total_sensors),
    attachment_ids=[att.id]
)
bag['total_devices'] = total_devices
bag['total_sensors'] = total_sensors
bag['attachment_id'] = att.id
bag['attachment_name'] = fname
bag['message'] = 'ODINS Get Devices - JSON generated: %d devices, %d sensors' % (total_devices, total_sensors)

remote = self.remote_id
cfg = {}
try:
    cfg = json.loads(remote.connection_params or '{}')
except Exception:
    cfg = {}
token = (cfg.get('token') or '').strip()
if not token:
    raise Exception("Missing ODINS token in connection_params.")
base_url = remote.base_url.rstrip('/')
headers = {'x-access-token': token}
sensors_plan = bag.get('sensors_plan', [])
if not sensors_plan:
    raise Exception("No sensors_plan found in bag. Run Build Sensors Plan first.")
total_readings_created = 0
errors = []
for plan_item in sensors_plan:
    device_parameter = plan_item.get('device_parameter')
    sensor_parameter = plan_item.get('sensor_parameter')
    sensor_id = plan_item.get('sensor_id')
    level = plan_item.get('level', '')
    initial_date = plan_item.get('initial_date')
    if not (device_parameter and sensor_parameter and sensor_id):
        continue
    try:
        url = '%s/backend/STH/v1/contextEntities/type/Device/id/%s/attributes/%s' % (base_url, device_parameter, sensor_parameter)
        params = []
        if initial_date:
            params.append('dateFrom=%sT00:00:00.000Z' % initial_date)
        params.append('dateTo=%sT23:59:59.999Z' % fields.Date.today())
        if params:
            url = url + '?' + '&'.join(params)
        resp = request_retry('GET', url, headers=headers, timeout=timeout)
        if resp.status_code >= 400:
            errors.append("Device %s, Sensor %s: %s" % (device_parameter, sensor_parameter, resp.status_code))
            continue
        data = resp.json() or {}
        context_responses = data.get('contextResponses', [])
        if not context_responses:
            continue
        context_element = context_responses[0].get('contextElement', {})
        attributes = context_element.get('attributes', [])
        if not attributes:
            continue
        values = attributes[0].get('values', [])
        for value_entry in values:
            recv_time = value_entry.get('recvTime')
            attr_value = value_entry.get('attrValue')
            if not recv_time:
                continue
            try:
                clean_time = recv_time.replace('Z', '').replace('T', ' ')
                if '.' in clean_time:
                    clean_time = clean_time.split('.')[0]
                measurement_time = fields.Datetime.from_string(clean_time)
            except ValueError:
                continue
            if attr_value is None:
                continue
            if isinstance(attr_value, list):
                if level is not None and level != '':
                    try:
                        level_index = int(level)
                        if level_index < len(attr_value):
                            try:
                                value = float(attr_value[level_index]) if attr_value[level_index] else 0.0
                            except (ValueError, TypeError):
                                continue
                            ts_str = measurement_time.strftime('%Y-%m-%d %H:%M:%S')
                            remote.upsert('mdm.measurement.device.sensor.reading', {'sensor_id': sensor_id, 'measurement_time': ts_str}, {'value': value})
                            total_readings_created += 1
                    except (ValueError, TypeError, IndexError):
                        continue
                else:
                    try:
                        for i, val in enumerate(attr_value):
                            if val:
                                try:
                                    value = float(val)
                                except (ValueError, TypeError):
                                    continue
                                ts_str = measurement_time.strftime('%Y-%m-%d %H:%M:%S')
                                remote.upsert('mdm.measurement.device.sensor.reading', {'sensor_id': sensor_id, 'measurement_time': ts_str}, {'value': value})
                                total_readings_created += 1
                                break
                    except TypeError:
                        continue
            else:
                try:
                    value = float(attr_value) if attr_value else 0.0
                except (ValueError, TypeError):
                    continue
                ts_str = measurement_time.strftime('%Y-%m-%d %H:%M:%S')
                remote.upsert('mdm.measurement.device.sensor.reading', {'sensor_id': sensor_id, 'measurement_time': ts_str}, {'value': value})
                total_readings_created += 1
    except Exception as e:
        errors.append("Device %s, Sensor %s: %s" % (device_parameter, sensor_parameter, str(e)))
audit = {
    'procedure': 'ODINS: Get Sensor Readings',
    'executed_at': fields.Datetime.now(),
    'total_sensors_processed': len(sensors_plan),
    'total_readings_created': total_readings_created,
    'total_errors': len(errors),
    'sensors': sensors_plan,
    'errors': errors
}
b64 = base64.b64encode(json.dumps(audit, ensure_ascii=False, indent=2).encode('utf-8'))
fname = 'odins_readings_%s.json' % fields.Datetime.now().replace(':', '').replace('-', '').replace(' ', '_')
att = env['ir.attachment'].create({
    'name': fname,
    'datas_fname': fname,
    'datas': b64,
    'mimetype': 'application/json',
    'res_model': 'remotecontrol',
    'res_id': remote.id
})
remote.message_post(
    body='[ODINS] upserts=%s errors=%s' % (total_readings_created, len(errors)),
    attachment_ids=[att.id]
)
bag['total_readings_created'] = total_readings_created
bag['total_sensors_processed'] = len(sensors_plan)
bag['errors'] = errors
bag['audit_attachment_id'] = att.id
bag['message'] = 'ODINS Get Sensor Readings - completed: %d readings created, %d sensors processed, %d errors' % (total_readings_created, len(sensors_plan), len(errors))
